// ontologynodeOption allows management of the mutation configuration using functional options.
type ontologynodeOption func(*OntologyNodeMutation)

// newOntologyNodeMutation creates new mutation for the OntologyNode entity.
func newOntologyNodeMutation(c config, op Op, opts ...ontologynodeOption) *OntologyNodeMutation {
	m := &OntologyNodeMutation{
		config:        c,
		op:            op,
		typ:           TypeOntologyNode,
		clearedFields: make(map[string]struct{}),
	}
	for _, opt := range opts {
		opt(m)
	}
	return m
}

// withOntologyNodeID sets the ID field of the mutation.
func withOntologyNodeID(id int) ontologynodeOption {
	return func(m *OntologyNodeMutation) {
		var (
			err   error
			once  sync.Once
			value *OntologyNode
		)
		m.oldValue = func(ctx context.Context) (*OntologyNode, error) {
			once.Do(func() {
				if m.done {
					err = errors.New("querying old values post mutation is not allowed")
				} else {
					value, err = m.Client().OntologyNode.Get(ctx, id)
				}
			})
			return value, err
		}
		m.id = &id
	}
}

// withOntologyNode sets the old OntologyNode of the mutation.
func withOntologyNode(node *OntologyNode) ontologynodeOption {
	return func(m *OntologyNodeMutation) {
		m.oldValue = func(context.Context) (*OntologyNode, error) {
			return node, nil
		}
		m.id = &node.ID
	}
}

